    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    top, bottom = min(r for r, c in pts), max(r for r, c in pts)
    left, right = min(c for r, c in pts), max(c for r, c in pts)
    markers = [(r, c) for r, c in pts
               if top < r < bottom and left < c < right]
    if not markers:
        return out
    mr, mc = markers[0]
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4

    # The marker is the origin of two 2-colored rays. A top-to-bottom ray
    # and a horizontal ray make a directional L; frame-notch positions set
    # the extents. The marker itself remains green.
    top_notches = [c for r, c in pts if r == top + 1 and c != left and c != right]
    left_notches = [r for r, c in pts if c == left + 1 and r not in (top, bottom)]
    if top_notches:
        # top-edge notch: draw up/left from the interior marker
        for c in range(max(left + 1, mc - 5), mc):
            out[mr][c] = 2
        for r in range(max(top + 1, mr - 5), mr):
            out[r][mc] = 2
    elif left_notches:
        # left-edge notch: draw right/down from the marker
        for c in range(mc + 1, min(right, mc + 6)):
            out[mr][c] = 2
        for r in range(mr + 1, min(bottom, mr + 6)):
            out[r][mc] = 2
    else:
        # centered marker: a square outline surrounding it
        for r in range(mr - 2, mr + 3):
            for c in range(mc - 2, mc + 3):
                if (r in (mr - 2, mr + 2) or c in (mc - 2, mc + 2)) and top < r < bottom and left < c < right:
                    out[r][c] = 2
    out[mr][mc] = 3
    return out
