    markers = [(r, c) for r, c in pts
               if top < r < bottom and left < c < right]
    if not markers:
        return out
    mr, mc = markers[0]
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4

    # A 3 immediately inside the left frame is the start of a diagonal
    # orientation key; otherwise the inner mark centers a square pattern.
    if grid[mr][left + 1] == 3:
        # Pattern is a 2-colored 5x5 square frame around the marker.
        for r in range(mr - 2, mr + 3):
            for c in range(mc - 2, mc + 3):
                if top < r < bottom and left < c < right and (
                        r in (mr - 2, mr + 2) or c in (mc - 2, mc + 2)):
                    out[r][c] = 2
    else:
        # The marker starts a vertical 5-cell line and horizontal 5-cell line
        # extending toward the nearest frame edge, preserving the green seed.
        for c in range(max(left + 1, mc - 5), mc):
            out[mr][c] = 2
        for r in range(max(top + 1, mr - 5), mr):
            out[r][mc] = 2
    out[mr][mc] = 3
    return out
