{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    top, bottom = min(r for r, c in pts), max(r for r, c in pts)
    left, right = min(c for r, c in pts), max(c for r, c in pts)
    interior = [(r, c) for r, c in pts if top < r < bottom and left < c < right]
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4
    if interior:
        mr, mc = interior[-1]
    else:
        mr, mc = (top + bottom) // 2, (left + right) // 2
    # The extra mark is a placement cue; the output uses the seed itself as
    # the center for a 5x5 ring.
    for r in range(mr - 2, mr + 3):
