    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    top, bottom = min(r for r, c in points), max(r for r, c in points)
    left, right = min(c for r, c in points), max(c for r, c in points)

    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4

    seeds = [(r, c) for r, c in points if top < r < bottom and left < c < right]
    if not seeds:
        # The left-edge protrusion is the seed at the inner-left boundary.
        seeds = [(r, left + 1) for r, c in points if c == left + 1 and top < r < bottom]
    if not seeds:
        return out
    sr, sc = seeds[-1]
    y, x = sr - (top + 1), sc - (left + 1)
    H, W = bottom - top - 1, right - left - 1

    if y == (H - 1) // 2 and x == (W - 1) // 2:
        for r in range(sr - 2, sr + 3):
            for c in range(sc - 2, sc + 3):
                if (r in (sr - 2, sr + 2) or c in (sc - 2, sc + 2)) and top < r < bottom and left < c < right:
                    out[r][c] = 2
    elif x == 0 or (y > (H - 1) // 2 and x < (W - 1) // 2):
        # Repeated Ls step up-right from the seed. Each has its horizontal
        # arm running left and vertical arm running down to the frame.
        yy, xx = y - 2, x + 2
        while yy >= 0 and xx < W:
            rr = top + 1 + yy
            cc = left + 1 + xx
            for cx in range(0, xx + 1):
                out[rr][left + 1 + cx] = 2
            for ry in range(yy, H):
                out[top + 1 + ry][cc] = 2
            yy -= 2
            xx += 2
    elif y == 0 or (y < (H - 1) // 2 and x > (W - 1) // 2):
        # Repeated Ls step down-left from the seed; arms run right and up.
        yy, xx = y + 2, x - 2
        while yy < H and xx >= -1:
            rr = top + 1 + yy
            for cx in range(max(0, xx), W):
                out[rr][left + 1 + cx] = 2
            if xx >= 0:
                for ry in range(0, yy + 1):
                    out[top + 1 + ry][left + 1 + xx] = 2
            yy += 2
            xx -= 2
    else:
        # Fallback for other seed locations: a square ring centered on it.
        for r in range(sr - 2, sr + 3):
