                if (r in (sr - 2, sr + 2) or c in (sc - 2, sc + 2)) and top < r < bottom and left < c < right:
                    out[r][c] = 2

    # Restore original green marker(s) after drawing the motif.
    for r, c in seeds:
        out[r][c] = 3
    return out
