 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    top, bottom = min(r for r, c in pts), max(r for r, c in pts)
    left, right = min(c for r, c in pts), max(c for r, c in pts)
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4
    seeds = [(r, c) for r, c in pts if top < r < bottom and left < c < right]
    if not seeds:
        return out
    sr, sc = seeds[0]
    H, W = bottom - top - 1, right - left - 1
    y, x = sr - top - 1, sc - left - 1

    # The interior seed selects a directional pattern. For a seed at the
    # upper-left edge, use the vertically reflected lower-left pattern.
    if x == 0 and y < H // 2:
        base = {
            (1, 3), (1, 5), (2, 3), (2, 5), (3, 3), (3, 5),
            (4, 0), (4, 1), (4, 2), (4, 5), (5, 5),
            (6, 0), (6, 1), (6, 2), (6, 3), (6, 4),
        }
        # Reflect/shift the lower-left motif so its green seed aligns here.
        for rr, cc in base:
            nr, nc = 7 - rr, cc - 1
            if 0 <= nr < H and 0 <= nc < W:
                out[top + 1 + nr][left + 1 + nc] = 2
        out[sr][sc] = 3
        return out

    # Center seed yields the square ring; other positions use the same ring
    # centered on the seed, clipped to the framed interior.
    for r in range(sr - 2, sr + 3):
        for c in range(sc - 2, sc + 3):
            if top < r < bottom and left < c < right and (
                    r in (sr - 2, sr + 2) or c in (sc - 2, sc + 2)):
                out[r][c] = 2
    out[sr][sc] = 3
    return out
