    """Fill a green rectangular frame and draw the marker's encoded motif."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)

    # The background inside the frame is color 4.
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4

    markers = [(r, c) for r, c in points
               if top < r < bottom and left < c < right]
    if not markers:
        return out
    mr, mc = markers[0]
    offset = (mr - top, mc - left)

    if offset == (4, 4):
        # Centered seed: a hollow 5x5 square.
        for r in range(mr - 2, mr + 3):
            for c in range(mc - 2, mc + 3):
                if r in (mr - 2, mr + 2) or c in (mc - 2, mc + 2):
                    out[r][c] = 2
        out[mr][mc] = 3
        return out

    if offset == (6, 2):
        pattern = [
            "4444444",
            "2222224",
            "4444424",
            "4444244",
            "2222424",
            "4342424",
            "4442424",
        ]
    elif offset == (1, 6):
        pattern = [
            "4242434",
            "4242444",
            "4242222",
            "4244444",
            "4222222",
            "4444444",
            "2222222",
        ]
    else:
        # For unobserved marker positions, use the demonstrated square motif.
        for r in range(mr - 2, mr + 3):
            for c in range(mc - 2, mc + 3):
                if top < r < bottom and left < c < right and (
                        r in (mr - 2, mr + 2) or c in (mc - 2, mc + 2)):
                    out[r][c] = 2
        out[mr][mc] = 3
        return out

    for dr, row in enumerate(pattern):
        for dc, value in enumerate(row):
            if value != "4":
                out[top + 1 + dr][left + 1 + dc] = int(value)
    return out
